def delta_bursty(n, d_min, P, J):
    if n <= 0:
        return 0
    return max((n - 1) * d_min, (n - 1) * P - J)

def get_equivalent_subtask_properties(fj_task, sigma, s):
    s_max = fj_task.num_stages
    s_hat = (s - 1) % s_max + 1 # Adjust for 1-based indexing if needed
    return fj_task.get_subtask_properties(sigma, s_hat)

def determine_critical_path(fj_task_i, s, stage_completion_candidates):
    max_candidate_time = 0
    critical_sigma = None
    for sigma, candidate_time in stage_completion_candidates.items():
        if candidate_time > max_candidate_time:
            max_candidate_time = candidate_time
            critical_sigma = sigma

    rho_s = {sigma: 0 for sigma in stage_completion_candidates.keys()}
    if critical_sigma is not None:
        rho_s[critical_sigma] = 1
    return rho_s, max_candidate_time

def get_subtask_event_model_approximation(subtask_tau_sigma_s_j, delta_t):
    parent_fj_task = subtask_tau_sigma_s_j.parent_fj_task
    return parent_fj_task.eta_func(delta_t)

def calculate_B_i_n(task_i, n, calculate_interference_IND, calculate_interference_FJ):
    B_current = n * task_i.C
    while True:
        interference_ind = calculate_interference_IND(task_i, B_current)
        interference_fj = calculate_interference_FJ(task_i, B_current)
        B_next = n * task_i.C + interference_ind + interference_fj
        if B_next == B_current:
            break
        B_current = B_next
    return B_current

def calculate_Q_i_n(task_i, n, calculate_interference_IND, calculate_interference_FJ):
    Q_current = (n - 1) * task_i.C
    while True:
        interference_ind = calculate_interference_IND(task_i, Q_current)
        interference_fj = calculate_interference_FJ(task_i, Q_current)
        Q_next = (n - 1) * task_i.C + interference_ind + interference_fj
        if Q_next == Q_current:
            break
        Q_current = Q_next
    return Q_current

def calculate_sub_event_model(fj_task_i, sigma, s, delta_t, eta_j_func, B_arrow_right_history, critical_path_history):
    if s == 1:
        return eta_j_func(delta_t)

    # Term 1: eta_j(delta_t)
    term1 = eta_j_func(delta_t)

    # Term 2: eta_j(B_arrow_right_sigma_s_minus_1_i + delta_t) - sum(...)
    # B_arrow_right_sigma_s_minus_1_i is the stage completion time for stage s-1 on core sigma for task Gamma_i
    B_prev_stage_completion = B_arrow_right_history.get((fj_task_i.id, sigma, s - 1), 0)
    total_events_up_to_current_point = eta_j_func(B_prev_stage_completion + delta_t)

    critical_events_accounted_for = 0
    for r in range(1, s):
        # Check if segment sigma was critical in stage r for task fj_task_i
        if critical_path_history.get((fj_task_i.id, sigma, r), 0) == 1:
            # This is a simplification. The paper implies eta_sigma_r_j_B_arrow_left_right_sigma_r_i
            # is the number of events processed by the critical path in stage r.
            # For a single job of the FJ task, this would typically be 1 if critical.
            critical_events_accounted_for += 1 # Simplified: one job per critical stage

    term2 = total_events_up_to_current_point - critical_events_accounted_for

    return min(term1, term2)

def calculate_stage_completion_window_candidate(fj_task_i, sigma, s, C_sigma_s_i, hp_ind_tasks, hp_fj_subtasks, sub_eta_func, get_subtask_priority):
    candidate_current = C_sigma_s_i
    while True:
        interference_ind = 0
        for hp_task_j in hp_ind_tasks:
            if hp_task_j.priority > get_subtask_priority(fj_task_i, sigma, s):
                # For independent tasks, sub_eta_func might just be their regular eta_func
                num_activations = sub_eta_func(hp_task_j, sigma, s, candidate_current) 
                interference_ind += num_activations * hp_task_j.C

        interference_fj = 0
        for hp_fj_subtask_j in hp_fj_subtasks:
            if hp_fj_subtask_j.priority > get_subtask_priority(fj_task_i, sigma, s):
                num_activations = sub_eta_func(hp_fj_subtask_j, sigma, s, candidate_current)
                interference_fj += num_activations * hp_fj_subtask_j.C

        candidate_next = C_sigma_s_i + interference_ind + interference_fj
        if candidate_next == candidate_current:
            break
        candidate_current = candidate_next
    return candidate_current

def calculate_stage_completion_time(fj_task_i, s, B_arrow_right_s_minus_1_i, stage_completion_candidates):
    max_stage_window = 0
    for sigma, candidate_time in stage_completion_candidates.items():
        if candidate_time > max_stage_window:
            max_stage_window = candidate_time
    return B_arrow_right_s_minus_1_i + max_stage_window

def calculate_busy_window(task, B_func, Q_func, delta_func):
    n = 1
    while True:
        B_n = B_func(task, n)
        Q_n_plus_1 = Q_func(task, n + 1)
        delta_n_plus_1 = delta_func(n + 1)

        if Q_n_plus_1 < delta_n_plus_1:
            return B_n
        n += 1
        # Add a safety break for non-converging cases or max iterations
        if n > MAX_N_FOR_BUSY_WINDOW_SEARCH:
            raise Exception("Busy window search exceeded max iterations")
